!(function (l) {
    "use strict";

    // Fungsi untuk toggle sidebar
    function toggleSidebar() {
        console.log("Toggle Sidebar clicked");
        const sidebar = l(".sidebar");

        // Di perangkat mobile (screen < 768px), toggle sidebar
        if (l(window).width() < 768) {
            l("body").toggleClass("sidebar-toggled");
            sidebar.toggleClass("toggled");
        } else {
            // Di desktop, toggle hanya untuk perubahan status (jika ingin menyembunyikan)
            l("body").toggleClass("sidebar-toggled");
            sidebar.toggleClass("toggled");
        }
    }

    // Cek lebar layar saat halaman dimuat
    function checkScreenSize() {
        // if (l(window).width() < 768) {
        // Di perangkat mobile, sembunyikan sidebar secara default
        // l("body").addClass("sidebar-toggled");
        // l(".sidebar").addClass("toggled");
        // } else {
        // Di desktop, pastikan sidebar selalu terlihat
        l("body").removeClass("sidebar-toggled");
        l(".sidebar").removeClass("toggled");
        // }
    }

    // Panggil checkScreenSize saat halaman dimuat
    checkScreenSize();

    // Cek ulang saat ukuran layar berubah (resize)
    l(window).resize(function () {
        checkScreenSize();
    });

    // Pastikan untuk menjalankan fungsi toggleSidebar setelah jQuery ready
    l(document).ready(function () {
        // Ketika tombol toggle sidebar di klik
        l("#sidebarToggle, #sidebarToggleTop").on("click", toggleSidebar);
    });

    // Fungsi untuk menangani scroll pada sidebar dan tampilan scroll to top
    l(window).resize(function () {
        l(window).width() < 768 && l(".sidebar .collapse").collapse("hide"),
            l(window).width() < 480 &&
                !l(".sidebar").hasClass("toggled") &&
                (l("body").addClass("sidebar-toggled"),
                l(".sidebar").addClass("toggled"),
                l(".sidebar .collapse").collapse("hide"));
    });

    l("body.fixed-nav .sidebar").on(
        "mousewheel DOMMouseScroll wheel",
        function (e) {
            var o;
            768 < l(window).width() &&
                ((o = (o = e.originalEvent).wheelDelta || -o.detail),
                (this.scrollTop += 30 * (o < 0 ? 1 : -1)),
                e.preventDefault());
        }
    );

    l(document).on("scroll", function () {
        100 < l(this).scrollTop()
            ? l(".scroll-to-top").fadeIn()
            : l(".scroll-to-top").fadeOut();
    });

    l(document).on("click", "a.scroll-to-top", function (e) {
        var o = l(this);
        l("html, body")
            .stop()
            .animate(
                { scrollTop: l(o.attr("href")).offset().top },
                1e3,
                "easeInOutExpo"
            ),
            e.preventDefault();
    });
})(jQuery);

function togglePasswordVisibility() {
    const passwordInput = document.getElementById("passwordInput");
    const passwordIcon = document.getElementById("passwordIcon");
    if (passwordInput.type === "password") {
        passwordInput.type = "text";
        passwordIcon.classList.remove("fa-eye");
        passwordIcon.classList.add("fa-eye-slash");
    } else {
        passwordInput.type = "password";
        passwordIcon.classList.remove("fa-eye-slash");
        passwordIcon.classList.add("fa-eye");
    }
}

