document.addEventListener("DOMContentLoaded", () => {
    const btn = document.getElementById("floatingSidebarToggle");
    const icon = document.getElementById("toggleIcon");
    let drag = false,
        startX,
        startY,
        startLeft,
        startTop;

    /* ===== Toggle sidebar on tap/click (unchanged) ===== */
    btn.addEventListener("click", (e) => {
        if (drag) {
            // kalau baru selesai geser, jangan sekaligus toggle sidebar
            drag = false;
            return;
        }
        document.body.classList.toggle("sidebar-toggled");
        document.querySelector(".sidebar")?.classList.toggle("toggled");
        icon.classList.toggle("fa-bars");
        icon.classList.toggle("fa-times");
    });

    /* ===== Drag handlers ===== */
    const onPointerDown = (e) => {
        drag = false; // reset flag
        startX = e.touches ? e.touches[0].clientX : e.clientX;
        startY = e.touches ? e.touches[0].clientY : e.clientY;
        const rect = btn.getBoundingClientRect();
        startLeft = rect.left;
        startTop = rect.top;

        document.addEventListener("pointermove", onPointerMove);
        document.addEventListener("pointerup", onPointerUp);
        document.addEventListener("touchmove", onPointerMove, {
            passive: false,
        });
        document.addEventListener("touchend", onPointerUp);
    };

    const onPointerMove = (e) => {
        e.preventDefault(); // blok scroll saat drag
        drag = true;
        const clientX = e.touches ? e.touches[0].clientX : e.clientX;
        const clientY = e.touches ? e.touches[0].clientY : e.clientY;

        let newLeft = startLeft + (clientX - startX);
        let newTop = startTop + (clientY - startY);

        /* keep inside viewport */
        const maxLeft = window.innerWidth - btn.offsetWidth - 8;
        const maxTop = window.innerHeight - btn.offsetHeight - 8;
        newLeft = Math.max(8, Math.min(maxLeft, newLeft));
        newTop = Math.max(8, Math.min(maxTop, newTop));

        btn.style.left = newLeft + "px";
        btn.style.top = newTop + "px";
        btn.style.right = "auto"; // reset right/bottom so left/top work
        btn.style.bottom = "auto";
    };

    const onPointerUp = () => {
        document.removeEventListener("pointermove", onPointerMove);
        document.removeEventListener("pointerup", onPointerUp);
        document.removeEventListener("touchmove", onPointerMove);
        document.removeEventListener("touchend", onPointerUp);
    };

    /* pointerdown & touchstart */
    btn.addEventListener("pointerdown", onPointerDown);
    btn.addEventListener("touchstart", onPointerDown, { passive: false });
});
